@page "/recipes/{Category}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@Category</li>
        </ol>
    </nav>

    <h1>@Category Recipes</h1>

    @if (recipes.Count == 0)
    {
        <p class="text-muted">No recipes found in this category yet.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private List<RecipeShare.Models.Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/recipes/@recipe.Category.ToLower()">@recipe.Category</a></li>
                <li class="breadcrumb-item active">@recipe.Title</li>
            }
        </ol>
    </nav>

    @if (recipe is null)
    {
        <p class="text-danger">Recipe not found.</p>
    }
    else
    {
        <h1>@recipe.Title</h1>
        <p class="text-muted">Category: @recipe.Category</p>

        <div class="row">
            <div class="col-md-4">
                <div class="card mb-4">
                    <div class="card-header"><strong>Ingredients</strong></div>
                    <ul class="list-group list-group-flush">
                        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li class="list-group-item">@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card mb-4">
                    <div class="card-header"><strong>Instructions</strong></div>
                    <div class="card-body">
                        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>

        <div class="card">
            <div class="card-body">
                <h5>Rate this Recipe</h5>
                <p class="text-muted mb-2">
                    Current rating: ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                </p>
                <StarRating RecipeId="recipe.Id" />
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeShare.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span
            class="star @(star <= hoveredStar ? "hovered" : "") @(star <= selectedStar ? "selected" : "")"
            @onmouseover="() => hoveredStar = star"
            @onmouseout="() => hoveredStar = 0"
            @onclick="() => Rate(star)"
            style="font-size: 1.8rem; cursor: pointer; user-select: none;">
            @(star <= (hoveredStar > 0 ? hoveredStar : selectedStar) ? "★" : "☆")
        </span>
    }
    @if (submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
</div>

<style>
    .star { color: #ccc; transition: color 0.15s; }
    .star.hovered, .star.selected { color: #ffc107; }
</style>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int hoveredStar;
    private int selectedStar;
    private bool submitted;

    private void Rate(int stars)
    {
        selectedStar = stars;
        RecipeService.RateRecipe(RecipeId, stars);
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@inject RecipeShare.Services.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    <EditForm Model="newRecipe" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="newRecipe.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => newRecipe.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="newRecipe.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat.Name">@cat.Name</option>
                }
            </InputSelect>
            <ValidationMessage For="() => newRecipe.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="newRecipe.Ingredients" placeholder="One ingredient per line" />
            <ValidationMessage For="() => newRecipe.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="newRecipe.Steps" placeholder="Step-by-step instructions" />
            <ValidationMessage For="() => newRecipe.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>

    @if (showSuccess)
    {
        <div class="alert alert-success mt-3">
            Recipe submitted successfully! <a href="/recipe/@submittedId">View it here</a>.
        </div>
    }
</div>

@code {
    private Recipe newRecipe = new();
    private bool showSuccess;
    private int submittedId;

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(newRecipe);
        submittedId = newRecipe.Id;
        showSuccess = true;
        newRecipe = new Recipe();
    }
}

